# Check if they form recognizable shapes
# Or maybe the task is simpler - count the number of regions?

from collections import Counter
def get_regions(grid, target_color):
    """Find connected components of target color"""
    visited = set()
    regions = []

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == target_color and (r,c) not in visited:
                # Found new region
                region = []
                stack = [(r,c)]
                while stack:
                    curr_r, curr_c = stack.pop()
                    if (curr_r, curr_c) in visited:
                        continue
                    visited.add((curr_r, curr_c))
                    region.append((curr_r, curr_c))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == target_color and (nr,nc) not in visited:
                                stack.append((nr,nc))
                regions.append(region)
    return regions

