# Count row types in each section
def count_row_types(section):
    types = {'empty': 0, 'uniform': 0}
    for row in section:
        nonzeros = [x for x in row if x != 0]
        if len(nonzeros) == 0:
            types['empty'] += 1
        else:
            types['uniform'] += 1
    return types

