# Try to detect if rows form connected horizontal patterns
# A row forms a "bar" if it has consecutive colored cells

def has_consecutive_cells(row):
    """Check if any two adjacent cells in row are both colored"""
    for c in range(len(row)-1):
        if row[c] != 0 and row[c+1] != 0:
            return True
    return False

