# For each cell, replace with how many times that color appears
def transform_by_color_count(grid):
    color_counts = {}
    for row in grid:
        for cell in row:
            color_counts[cell] = color_counts.get(cell, 0) + 1

    new_grid = [[color_counts[cell]] for row in grid for cell in row]
    return new_grid

